function toast(text,type='success'){const el=document.createElement('div');el.className=`toast ${type}`;el.innerHTML=icon(type==='error'?'help':'check')+`<span>${esc(text)}</span>`;$('#toasts').append(el);setTimeout(()=>el.remove(),4500);}
function persist(){clearTimeout(saveTimer);saving=true;saveError=false;updateStatus();saveTimer=setTimeout(async()=>{try{await writeWorkspace(clone(workspace));saving=false;saveError=false;}catch(e){saving=false;saveError=true;toast('Sauvegarde locale impossible. Exportez votre projet pour le conserver.','error');}updateStatus();},250);}
