function phantomBadge(c){const available=phantomAvailable(c),label=c.bank?.startsWith('SB:')?(c.phantom?'48 V stagebox prévu ON':'48 V stagebox prévu OFF'):c.phantom?'48 V activé':available?'48 V désactivé':'48 V à gérer en amont';return `<span class="phantom-badge ${c.phantom?'on':available?'off':'upstream'}" role="img" aria-label="${label}" title="${label}">${icon('bolt',11)}<span>48 V</span><b>${c.phantom?'ON':available?'OFF':'—'}</b></span>`;}
function phantomPanel(c){const available=phantomAvailable(c),source=`${bankOptions(show()).find(([id])=>id===c.bank)?.[1]||BANKS[c.bank]||c.bank} ${number(c.input)}${c.mode!=='M'?'–'+number(c.input+1):''}`;return `<div class="phantom-panel ${c.phantom?'powered':''} ${available?'':'unavailable'}"><div class="phantom-copy"><span class="phantom-symbol">${icon('bolt',15)}</span><div><b>Alimentation fantôme</b><small><span class="phantom-state">${c.bank?.startsWith('SB:')?(c.phantom?'48 V prévu sur la stagebox':'48 V stagebox prévu OFF'):c.phantom?'48 V activé':available?'48 V désactivé':'Alimentation en amont'}</span><span class="phantom-source">${esc(source)}</span></small></div></div><button type="button" class="phantom-switch ${c.phantom?'on':''}" data-action="phantom" role="switch" aria-checked="${!!c.phantom}" aria-label="Alimentation fantôme 48 V" ${available?'':'disabled'}><span class="phantom-switch-label">${c.phantom?'ON':'OFF'}</span><span class="phantom-switch-thumb" aria-hidden="true"></span></button></div>`;}

